-- Auto-generated playlists are rebuilt by the sync workers from library data, so only playlists
-- users make themselves are audited.
CREATE OR REPLACE FUNCTION audit_playlists_changes()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    BEGIN
        IF TG_OP = 'INSERT' AND NOT NEW."IsAutoGenerated" THEN
            PERFORM audit_write('Playlist', NEW."Id", 'PlaylistCreated', 'Create',
                jsonb_build_object('name', NEW."Name"),
                NEW."OwnerId", NULL, NEW."Name");

        ELSIF TG_OP = 'UPDATE' AND NOT NEW."IsAutoGenerated" THEN
            IF OLD."Name" IS DISTINCT FROM NEW."Name" THEN
                PERFORM audit_write('Playlist', NEW."Id", 'PlaylistRenamed', 'Update',
                    jsonb_build_object('old', OLD."Name", 'new', NEW."Name"),
                    NEW."OwnerId", NULL, NEW."Name");
            END IF;

            IF OLD."DeletedAt" IS NULL AND NEW."DeletedAt" IS NOT NULL THEN
                PERFORM audit_write('Playlist', NEW."Id", 'PlaylistSoftDeleted', 'Delete',
                    jsonb_build_object('name', NEW."Name", 'deleted_at', NEW."DeletedAt"),
                    NEW."OwnerId", NULL, NEW."Name");
            END IF;

            IF OLD."DeletedAt" IS NOT NULL AND NEW."DeletedAt" IS NULL THEN
                PERFORM audit_write('Playlist', NEW."Id", 'PlaylistRestored', 'Update',
                    jsonb_build_object('name', NEW."Name"),
                    NEW."OwnerId", NULL, NEW."Name");
            END IF;

        ELSIF TG_OP = 'DELETE' AND NOT OLD."IsAutoGenerated" THEN
            PERFORM audit_write('Playlist', OLD."Id", 'PlaylistDeletedPermanently', 'Delete',
                jsonb_build_object('name', OLD."Name"),
                OLD."OwnerId", NULL, OLD."Name");
        END IF;

    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'Audit logging failed for % %: %', TG_TABLE_NAME, TG_OP, SQLERRM;
    END;

    RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS playlists_audit_trigger ON "Playlists";

CREATE TRIGGER playlists_audit_trigger
    AFTER INSERT OR DELETE OR UPDATE OF "Name", "DeletedAt"
    ON "Playlists"
    FOR EACH ROW
    EXECUTE FUNCTION audit_playlists_changes();
